import { describe, it, expect, beforeEach } from '@jest/globals';
import request from 'supertest';
import { resetRateLimiterState } from '../../src/middleware/rateLimiter';

describe('Debug JWT Auth', () => {
  let app: any;

  beforeEach(async () => {
    // Reset rate limiter state to avoid test interference
    resetRateLimiterState();
    
    // Import the actual app
    const appModule = await import('../../src/index');
    app = appModule.app;
    
    // Give the app a moment to initialize
    await new Promise((resolve) => setTimeout(resolve, 100));
  });

  it('should register user and use token for auth', async () => {
    const uniqueEmail = `jwt-debug-${Date.now()}@example.com`;
    const testUser = {
      email: uniqueEmail,
      password: 'SecureTestPassword123!',
      name: 'Test User',
    };

    // Step 1: Register
    console.log('Step 1: Registering user...');
    const registerResponse = await request(app)
      .post('/api/auth/register')
      .send(testUser);

    console.log('Registration status:', registerResponse.status);
    console.log('Registration body:', JSON.stringify(registerResponse.body, null, 2));

    expect(registerResponse.status).toBe(201);
    
    const token = registerResponse.body.accessToken || registerResponse.body.token;
    console.log('Token received:', token ? `${token.substring(0, 30)}...` : 'NO TOKEN');

    // Step 2: Use token to access protected route
    console.log('\nStep 2: Accessing /api/auth/me with token...');
    const meResponse = await request(app)
      .get('/api/auth/me')
      .set('Authorization', `Bearer ${token}`);

    console.log('Me response status:', meResponse.status);
    console.log('Me response body:', JSON.stringify(meResponse.body, null, 2));

    expect(meResponse.status).toBe(200);
    expect(meResponse.body.user).toBeDefined();
    expect(meResponse.body.user.email).toBe(uniqueEmail);
  });

  it('should check what auth middleware expects', async () => {
    // Test with a manually created valid token
    const { default: jwt } = await import('jsonwebtoken');
    const testToken = jwt.sign(
      { userId: 1, email: 'test@example.com' },
      process.env.JWT_SECRET || 'test-secret-key'
    );

    console.log('Manual token:', testToken.substring(0, 30) + '...');

    const response = await request(app)
      .get('/api/auth/me')
      .set('Authorization', `Bearer ${testToken}`);

    console.log('Response with manual token:', response.status, response.body);
  });
});